<?php
declare(strict_types=1);
session_start();
require_once __DIR__ . '/config/helpers.php'; require_once __DIR__ . '/config/pdo.php'; require_once __DIR__ . '/config/saas_billing.php';
saas_billing_ensure_schema($pdo);
$companySlug = trim((string)($_GET['company'] ?? '')); $company = $companySlug !== '' ? saas_find_company_by_slug_any_status($pdo, $companySlug) : null; if (!$company) { http_response_code(404); exit('Empresa não encontrada.'); }
$chargeId = (int)($_GET['charge'] ?? 0); $charge = $chargeId > 0 ? saas_get_charge($pdo, $chargeId, (int)$company['id']) : saas_find_latest_open_charge($pdo, (int)$company['id']); if (!$charge) { http_response_code(404); exit('Cobrança não encontrada para esta empresa.'); }
$erro=''; if ($_SERVER['REQUEST_METHOD'] === 'POST') { try { $action=(string)($_POST['action'] ?? 'sync'); if($action==='card'){ $plan=saas_find_plan($pdo,(int)$charge['plan_id']); if(!$plan) throw new RuntimeException('Plano não encontrado.'); $card=saas_create_card_checkout($pdo,$company,$plan,!empty($charge['subscription_id'])?(int)$charge['subscription_id']:null,'Assinatura do plano '.(string)$plan['name']); $url=(string)($card['checkout_url'] ?? ''); if($url==='') throw new RuntimeException('Checkout de cartão indisponível.'); header('Location: '.$url); exit; } $charge = saas_sync_charge_status($pdo, (int)$charge['id']); } catch (Throwable $e) { $erro = $e->getMessage(); } }
$signup = $_SESSION['signup_success'] ?? null; $belongs = is_array($signup) && (int)($signup['company_id'] ?? 0) === (int)$company['id']; $isPaid = strtolower((string)$charge['status']) === 'paid';
?><!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Pagamento da assinatura</title><link rel="stylesheet" href="/assets/admin.css"><style>body{margin:0;background:#f5f7fb;font-family:Arial,Helvetica,sans-serif;color:#0f172a}.wrap{max-width:980px;margin:32px auto;padding:0 16px}.hero{background:linear-gradient(135deg,#0f172a 0%, #147a8a 100%);color:#fff;padding:26px;border-radius:24px;box-shadow:0 18px 45px rgba(15,23,42,.12)}.grid{display:grid;grid-template-columns:1.1fr .9fr;gap:16px;margin-top:16px}.card{background:#fff;border:1px solid #e8eef5;border-radius:22px;padding:22px;box-shadow:0 12px 32px rgba(2,6,23,.06)}.code{background:#0f172a;color:#e2e8f0;border-radius:18px;padding:16px;word-break:break-all;font-family:monospace;font-size:14px}.kpis{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:16px}.kpi{background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.15);padding:14px;border-radius:16px}.badge{display:inline-flex;padding:8px 12px;border-radius:999px;font-weight:700;border:1px solid #bfdbfe;background:#eff6ff;color:#1d4ed8}.paid{background:#ecfdf5;border-color:#a7f3d0;color:#065f46}.error{background:#fef2f2;border-color:#fecaca;color:#991b1b}.qrimg{max-width:100%;border-radius:18px;border:1px solid #e2e8f0;background:#fff;padding:8px}@media (max-width:900px){.grid{grid-template-columns:1fr}.kpis{grid-template-columns:1fr}}</style></head><body><div class="wrap"><section class="hero"><div style="display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;align-items:flex-start;"><div><div style="font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:#dbeafe;font-weight:700;">Assinatura SaaS</div><h1 style="margin:8px 0 10px;font-size:34px;line-height:1.05;">Pagamento da assinatura</h1><p style="margin:0;color:#dbeafe;max-width:680px;">Empresa <strong><?= e((string)$company['name']) ?></strong> • Plano <strong><?= e((string)$charge['plan_name']) ?></strong>. Assim que o pagamento for confirmado, o desbloqueio do SaaS acontece automaticamente.</p></div><div><span id="charge-status" class="badge <?= $isPaid ? 'paid' : (in_array(strtolower((string)$charge['status']), ['error','expired'], true) ? 'error' : '') ?>"><?= e(saas_charge_status_label((string)$charge['status'])) ?></span></div></div><div class="kpis"><div class="kpi"><div style="font-size:12px;color:#dbeafe;">Valor</div><div style="font-size:26px;font-weight:800;"><?= money((float)$charge['amount']) ?></div></div><div class="kpi"><div style="font-size:12px;color:#dbeafe;">Expira em</div><div style="font-size:20px;font-weight:800;"><?= e((string)($charge['expires_at'] ?? '—')) ?></div></div><div class="kpi"><div style="font-size:12px;color:#dbeafe;">TXID</div><div style="font-size:16px;font-weight:800;word-break:break-word;"><?= e((string)$charge['txid']) ?></div></div></div></section><?php if ($erro): ?><div class="toast toast-error" style="margin-top:14px;"><?= e($erro) ?></div><?php endif; ?><div class="grid"><section class="card"><h3 style="margin-top:0;">Pix copia e cola</h3><?php if (!$isPaid): ?><p style="color:#475569;line-height:1.6;">Copie o código abaixo e pague no aplicativo do seu banco. Você também pode clicar em <strong>Já paguei</strong> para forçar uma nova consulta ao PagBank.</p><div class="code" id="pix-copy-value"><?= e((string)($charge['pix_copy_paste'] ?? '')) ?></div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:14px;"><button class="btn" type="button" onclick="copyPix()">Copiar código Pix</button><form method="post" style="display:inline;"><input type="hidden" name="action" value="sync"><button class="btn btn-ghost" type="submit">Já paguei</button></form><form method="post" style="display:inline;"><input type="hidden" name="action" value="card"><button class="btn" type="submit">Pagar com cartão</button></form></div><?php else: ?><p style="color:#065f46;font-weight:700;">Pagamento confirmado em <?= e((string)($charge['paid_at'] ?? '')) ?>.</p><?php endif; ?><?php if ($belongs): ?><div class="card" style="padding:18px;margin-top:18px;background:#f8fafc;"><h4 style="margin:0 0 8px;">Dados da sua empresa</h4><p style="margin:0 0 8px;"><strong>Login:</strong> <?= e((string)($signup['email'] ?? '')) ?></p><p style="margin:0 0 8px;"><strong>Senha inicial:</strong> <?= e((string)($signup['pass'] ?? '')) ?></p><?php if (!empty($signup['catalog_url_path'])): ?><p style="margin:0 0 8px;"><strong>Catálogo de pedidos:</strong> <a href="<?= e((string)$signup['catalog_url_path']) ?>"><?= e((string)$signup['catalog_url_path']) ?></a></p><?php endif; ?><?php if (!empty($signup['public_catalog_url'])): ?><p style="margin:0;"><strong>Catálogo público:</strong> <a href="<?= e((string)$signup['public_catalog_url']) ?>"><?= e((string)$signup['public_catalog_url']) ?></a></p><?php endif; ?></div><?php endif; ?></section><aside class="card"><h3 style="margin-top:0;">QR Code</h3><?php if (!$isPaid && !empty($charge['qr_image'])): ?><?php $src = (string)$charge['qr_image']; if (!str_starts_with($src, 'data:')) $src = 'data:image/png;base64,' . $src; ?><img class="qrimg" src="<?= e($src) ?>" alt="QR Code Pix"><?php elseif (!$isPaid): ?><div style="padding:20px;border:1px dashed #cbd5e1;border-radius:18px;color:#475569;">O PagBank não retornou a imagem do QR Code nesta resposta. O pagamento pode ser feito normalmente usando o código copia e cola.</div><?php else: ?><div style="padding:20px;border:1px solid #a7f3d0;border-radius:18px;background:#ecfdf5;color:#065f46;font-weight:700;">Pagamento confirmado e desbloqueio automático concluído.</div><?php endif; ?><div style="margin-top:18px;color:#475569;line-height:1.6;"><strong>Link de acompanhamento:</strong><br><code><?= e((string)($charge['payment_url'] ?? '')) ?></code></div></aside></div></div><script>async function refreshStatus(){const url=<?= json_encode('/pix_status.php?company=' . rawurlencode((string)$company['slug']) . '&charge=' . (int)$charge['id']) ?>; try{const resp=await fetch(url,{cache:'no-store'}); const data=await resp.json(); if(!data||!data.ok)return; const badge=document.getElementById('charge-status'); badge.textContent=data.label; badge.className='badge'+(data.paid?' paid':''); if(data.paid){window.location.reload();}}catch(e){}} function copyPix(){const text=document.getElementById('pix-copy-value').innerText; navigator.clipboard.writeText(text).then(()=>alert('Código Pix copiado.'));} setInterval(refreshStatus,10000);</script></body></html>